pub fn html_escape(&self) -> Cow<'_, str> {
    let mut escaped = String::new();
    for c in self.as_str().chars() {
        match c {
            '&' => escaped.push_str("&amp;"),
            '<' => escaped.push_str("&lt;"),
            '>' => escaped.push_str("&gt;"),
            '"' => escaped.push_str("&quot;"),
            '\'' => escaped.push_str("&apos;"),
            '/' => escaped.push_str("&sol;"),
            '`' => escaped.push_str("&grave;"),
            _ => escaped.push(c),
        }
    }
    Cow::Owned(escaped)
}
